from collections import deque
def solve(data):
    graph = [[] for _ in range(data['n'])]
    for u, v in data['edges']:
        graph[u].append(v)
        graph[v].append(u)
    dist = [-1] * data['n']
    dist[data['start']] = 0
    queue = deque([data['start']])
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)
    return dist

import heapq
def solve(data):
    k = data['k']
    if k == 0:
        return []
    heap = []
    for value in data['values']:
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:
            heapq.heapreplace(heap, value)
    return sorted(heap, reverse=True)

